let task = Task {
    await withTaskCancellationHandler {
        while !Task.isCancelled {               // safe point
            try? await handleNext()
        }
    } onCancel: {
        stream.cancel()                          // wake a suspended operation
    }
    await flushAndRelease()                      // phase 2 cleanup
}

task.cancel()                                    // phase 1: request
_ = try? await task.value                        // phase 2: completion

let flagQueue = DispatchQueue(label: "stop")
var stopping = false
let group = DispatchGroup()
group.enter()
DispatchQueue.global().async(group: group) {
    defer { group.leave() }
    while !(flagQueue.sync { stopping }) {        // safe point
        handleNext()
    }
    flushAndRelease()                            // phase 2 cleanup
}

flagQueue.sync { stopping = true }               // phase 1: request
group.wait()                                     // phase 2: completion

